def parse_nested_parens(paren_string: str) -> List[int]:
    max_nesting = []
    nesting_level = 0
    for char in paren_string:
        if char == '(':
            nesting_level += 1
            max_nesting.append(nesting_level)
        elif char == ')':
            if nesting_level > 0:
                nesting_level -= 1
                if nesting_level == 0:
                    max_nesting.pop()
    return max_nesting
